css:
.loader { position: relative; display: inline-block; overflow: hidden; width: var(--loader-size); height: var(--loader-size); border-radius: 9999px; border: calc(var(--loader-size) * .025) solid color-mix(in srgb, var(--loader-color) 35%, transparent); background: radial-gradient(circle, transparent 54%, color-mix(in srgb, var(--loader-color) 14%, transparent) 55%); }
.loader::after { content: ''; position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; background: conic-gradient(from 0deg, color-mix(in srgb, var(--loader-color) 70%, transparent), transparent 90deg); animation: twSpin calc(var(--loader-speed) * 1.4) linear infinite; }
@keyframes twSpin { to { transform: rotate(360deg); } }
